def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    from collections import defaultdict
    diag=defaultdict(list)
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if v!=g[0][0] or True:
                pass
    # treat each color separately, using its own majority background
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    # main diagonals (r-c) and anti-diagonals (r+c)
    def extend(cells_idx, delta):
        # cells_idx: sorted list of (r,c) along a diagonal; delta step direction
        r,c=cells_idx[-1]; v=g[r][c]
        while True:
            r+=delta[0]; c+=delta[1]
            if not(0<=r<h and 0<=c<w) or g[r][c]!=bg: break
            out[r][c]=v
        r,c=cells_idx[0]
        while True:
            r-=delta[0]; c-=delta[1]
            if not(0<=r<h and 0<=c<w) or g[r][c]!=bg: break
            out[r][c]=v
    for key,delta in (('m',(1,1)),('a',(1,-1))):
        groups=defaultdict(list)
        for i in range(h):
            for j in range(w):
                if g[i][j]!=bg:
                    groups[(g[i][j], i-j if key=='m' else i+j)].append((i,j))
        for k,pts in groups.items():
            if len(pts)>=2:
                pts.sort()
                extend(pts,delta)
    return out
